/*
 * A trace waterfall: spans as bars on a time axis, nested by depth, coloured by
 * group, zoomed and panned by the wheel and a drag.
 */
typedef struct KitWaterfall {
    /*
     * The spans: fields `name`, `start`, `len` (ms), `depth`, `group`, and
     * `target` (a label).
     */
    const KuiChannel *bars;
    /*
     * Points in time, fields `at` and `label`: a navigation, a paint.
     */
    const KuiChannel *marks;
    /*
     * The window's start in ms: yours to keep, from `zoom`.
     */
    double start;
    bool start_set;
    /*
     * The window's length in ms; the whole trace when left out.
     */
    double length;
    bool length_set;
    /*
     * The selected span (its row).
     */
    int64_t selected;
    bool selected_set;
    /*
     * Takes the room its parent leaves.
     */
    bool grow;
    bool grow_set;
    /*
     * The message `select` arrives as, consumed; NULL for none. A span was
     * clicked.
     */
    KuiValue *on_select;
    /*
     * The message `zoom` arrives as, consumed; NULL for none. The wheel or a
     * drag asks for another window.
     */
    KuiValue *on_zoom;
    /* Keys the instance (empty: where it is placed); fresh asks the
     * extension every frame instead of replaying. */
    KuiStr key;
    bool fresh;
} KitWaterfall;

static inline KuiValue *kit_waterfall_props(const KitWaterfall *p) {
    KuiValue *m = kui_value_map();
    if (p->bars != NULL) kui_value_map_set(m, KUI_STR("bars"), kui_channel_handle(p->bars));
    if (p->marks != NULL) kui_value_map_set(m, KUI_STR("marks"), kui_channel_handle(p->marks));
    if (p->start_set) kui_value_map_set(m, KUI_STR("start"), kui_value_float(p->start));
    if (p->length_set) kui_value_map_set(m, KUI_STR("length"), kui_value_float(p->length));
    if (p->selected_set) kui_value_map_set(m, KUI_STR("selected"), kui_value_int(p->selected));
    if (p->grow_set) kui_value_map_set(m, KUI_STR("grow"), kui_value_bool(p->grow));
    if (p->on_select != NULL) kui_value_map_set(m, KUI_STR("on_select"), p->on_select);
    if (p->on_zoom != NULL) kui_value_map_set(m, KUI_STR("on_zoom"), p->on_zoom);
    if (p->key.len > 0) kui_value_map_set(m, KUI_STR("key"), kui_value_str(p->key));
    if (p->fresh) kui_value_map_set(m, KUI_STR("fresh"), kui_value_bool(true));
    return m;
}

/* Places kit/waterfall: a KUI_SLOT_* code, KUI_SLOT_UNDECLARED when nothing provides it. */
static inline int32_t kit_waterfall(KuiCtx *ctx, const KitWaterfall *p) {
    KuiValue *props = kit_waterfall_props(p);
    int32_t fill = kui_component(ctx, KUI_STR(KIT_NAMESPACE "/waterfall"), props, NULL, NULL);
    kui_value_free(props);
    return fill;
}

